      galaxy_wish: `${D(LG("ga-ws-t", [[0, "#FF9BD6", 0], [.5, "#C04EE6", .75], [1, "#8C6FF5"]], 0, 1, 1, 0), LG("ga-ws-s", [[0, "#FFF6B8"], [1, "#FFC93A"]]))}<path d="M3 61C13 48 24 37 34 31L44 44C31 49 17 55 3 61Z" fill="url(#ga-ws-t)"/><path d="M8 58C18 48 27 41 36 36" fill="none" stroke="#fff" stroke-width="2.4" stroke-linecap="round" opacity=".75"/><path d="${RSTAR(43, 23, 20, 10)}" fill="url(#ga-ws-s)" ${SO}/>${EYES(38, 48, 24, 2.3)}${SMILE(43, 29, 2.5)}${BLUSH(34.5, 51.5, 28.5)}<path d="${SPK(13, 16, 5)}" fill="#C5BCF5" ${OL(1.6)}/><circle cx="22" cy="9" r="2" fill="#FF9BD6"/>`,
